INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20KPXCL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $23$ meters and a width of $9$ meters. What is the area of the garden, in square meters?', NULL, $lyceon_json$[{"key":"A","text":"$207$"},{"key":"B","text":"$64$"},{"key":"C","text":"$32$"},{"key":"D","text":"$414$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $23 \\times 9 = 207$ square meters. The answer $64$ comes from computing the perimeter $2(23 + 9) = 64$ instead of the area. The answer $32$ results from adding the dimensions ($23 + 9 = 32$) without any multiplication. The answer $414$ comes from doubling the area, possibly confusing with a related formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20L2PDV', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A catering company charges a $\\$47$ setup fee plus $\\$13$ per guest. A client wants to spend more than $\\$125$ but no more than $\\$203$ on catering. How many whole-number values of $g$, the number of guests, satisfy both conditions?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The total cost is $47 + 13g$. The compound inequality is $125 < 47 + 13g \\leq 203$. Subtracting $47$ from all three parts gives $78 < 13g \\leq 156$. Dividing by $13$ yields $6 < g \\leq 12$. The whole-number values of $g$ that satisfy this are $7, 8, 9, 10, 11, 12$, which is $6$ values. A common error is to include $g = 6$, which gives a cost of exactly $\\$125$, violating the strict inequality. Another error is to exclude $g = 12$, which gives a cost of exactly $\\$203$ and is permitted by the non-strict upper bound.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21OJGZE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A solution is prepared by mixing chemical $X$ and chemical $Y$ in a ratio of $5:3$ by volume. The density of chemical $X$ is $1.13$ grams per milliliter and the density of chemical $Y$ is $0.87$ grams per milliliter. What is the total mass, in grams, of 640 milliliters of this solution?', NULL, $lyceon_json$[{"key":"A","text":"$652.0$"},{"key":"B","text":"$660.8$"},{"key":"C","text":"$640.0$"},{"key":"D","text":"$619.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $660.8$ grams. In a $5:3$ ratio by volume, 640 mL contains $\\frac{5}{8} \\times 640 = 400$ mL of chemical $X$ and $\\frac{3}{8} \\times 640 = 240$ mL of chemical $Y$. The mass of $X$ is $400 \\times 1.13 = 452$ grams and the mass of $Y$ is $240 \\times 0.87 = 208.8$ grams. The total mass is $452 + 208.8 = 660.8$ grams. The result $640.0$ assumes a density of $1$ g/mL for the entire solution, ignoring the different densities. The result $619.2$ comes from swapping the densities, assigning $0.87$ g/mL to $X$ and $1.13$ g/mL to $Y$: $400 \\times 0.87 + 240 \\times 1.13 = 348 + 271.2 = 619.2$. The result $652.0$ comes from an arithmetic slip in computing $240 \\times 0.87$ as $200.0$ instead of $208.8$, giving $452 + 200 = 652$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21S61MQ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $DEF$ with the right angle at $E$, $\\sin(D) = \\frac{5}{13}$. What is $\\cos(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{13}$"},{"key":"B","text":"$\\frac{12}{13}$"},{"key":"C","text":"$\\frac{5}{12}$"},{"key":"D","text":"$\\frac{5}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\sin(D) = \\frac{5}{13}$, the side opposite $D$ is $5$ and the hypotenuse is $13$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore $\\cos(D) = \\frac{12}{13}$. The answer $\\frac{8}{13}$ comes from subtracting $13 - 5 = 8$ instead of using the Pythagorean theorem. The answer $\\frac{5}{12}$ confuses cosine with tangent. The answer $\\frac{5}{13}$ incorrectly assumes sine and cosine of the same angle are equal.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2350SRE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 4x + 2y - 20 = 0$. A line tangent to this circle at the point $(5, 3)$ has which of the following slopes?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{4}$"},{"key":"B","text":"$\\frac{4}{3}$"},{"key":"C","text":"$\\frac{3}{4}$"},{"key":"D","text":"$-\\frac{4}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite the equation in standard form by completing the square: $(x^2 - 4x + 4) + (y^2 + 2y + 1) = 20 + 4 + 1$, giving $(x - 2)^2 + (y + 1)^2 = 25$. The center is $(2, -1)$ and the radius is $5$. Verify the point $(5, 3)$ is on the circle: $(5-2)^2 + (3+1)^2 = 9 + 16 = 25$. The slope of the radius from $(2, -1)$ to $(5, 3)$ is $\\frac{3 - (-1)}{5 - 2} = \\frac{4}{3}$. Since the tangent line is perpendicular to the radius, the tangent slope is the negative reciprocal: $-\\frac{3}{4}$. The answer $\\frac{4}{3}$ is the slope of the radius itself, not the tangent. The answer $\\frac{3}{4}$ results from taking the reciprocal of the radius slope without negating. The answer $-\\frac{4}{3}$ comes from negating the radius slope without taking the reciprocal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23J7OR3', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'What is the value of $y$ in the solution to the following system of equations? $$\\begin{cases} 3x + 5y = 51 \\\\ 3x - 2y = 9 \\end{cases}$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Subtracting the second equation from the first eliminates $x$: $(3x + 5y) - (3x - 2y) = 51 - 9$, which simplifies to $7y = 42$, giving $y = 6$. Substituting back confirms $3x + 30 = 51$, so $x = 7$, and checking the second equation: $21 - 12 = 9$. A common error is to add the equations instead of subtracting, which would give $6x + 3y = 60$ and require additional work that may lead to arithmetic mistakes.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24H2LZG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{9a^3b^5}{3a^{-1}b^2} \\cdot \\frac{2b}{a^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$6a^2b^4$"},{"key":"B","text":"$6a^4b^4$"},{"key":"C","text":"$6a^2b^3$"},{"key":"D","text":"$18a^2b^4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Simplify the first fraction: $\\frac{9a^3b^5}{3a^{-1}b^2} = 3a^{3-(-1)}b^{5-2} = 3a^4b^3$. Multiplying by $\\frac{2b}{a^2}$ gives $\\frac{6a^4b^4}{a^2} = 6a^{4-2}b^4 = 6a^2b^4$. The expression $6a^4b^4$ results from not dividing by $a^2$ in the second multiplication, reflecting a gap in applying exponent rules. The expression $6a^2b^3$ comes from an arithmetic slip in the $b$ exponent, computing $b^3 \\cdot b$ as $b^3$ instead of $b^4$. The expression $18a^2b^4$ results from multiplying the coefficients as $9 \\times 2 = 18$ without first simplifying $\\frac{9}{3} = 3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25HL6Y8', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $6x + 11 = 53$?', NULL, $lyceon_json$[{"key":"A","text":"5"},{"key":"B","text":"7"},{"key":"C","text":"8"},{"key":"D","text":"10"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting 11 from both sides gives $6x = 42$. Dividing both sides by 6 gives $x = 7$. The distractor 5 results from a subtraction error. The distractor 8 comes from incorrectly dividing 53 by 6 and rounding. The distractor 10 results from dividing 53 minus 11 incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25OKH14', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. If one angle measures $62^\\circ$, what is the measure of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$28^\\circ$"},{"key":"B","text":"$62^\\circ$"},{"key":"C","text":"$118^\\circ$"},{"key":"D","text":"$128^\\circ$"}]$lyceon_json$::jsonb, 'C', NULL, E'Supplementary angles sum to $180^\\circ$. Therefore the other angle measures $180^\\circ - 62^\\circ = 118^\\circ$. The distractor $28^\\circ$ confuses supplementary with complementary ($90^\\circ - 62^\\circ$). The distractor $62^\\circ$ assumes the angles are equal. The distractor $128^\\circ$ results from an arithmetic error in subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26YMDZ9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A two-way frequency table summarizes the lunch preferences of $83$ employees at a company.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274YYQM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist wants to determine whether a new vitamin supplement improves energy levels. She recruits $80$ volunteers and randomly assigns $40$ to take the supplement daily and $40$ to take a placebo for $8$ weeks. Neither the participants nor the nutritionist know who receives the supplement. This study is best described as which of the following?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A survey"},{"key":"C","text":"A randomized controlled experiment"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a randomized controlled experiment because participants are randomly assigned to a treatment group (supplement) or a control group (placebo), and the study is double-blind. An observational study does not involve random assignment to treatment groups. A survey collects self-reported data without any intervention. A case study examines a single individual or small group in depth rather than using random assignment with a control.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28074Z8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, angle $P$ measures $37^\\circ$ and the exterior angle at vertex $R$ measures $109^\\circ$. What is the measure of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$34^\\circ$"},{"key":"B","text":"$72^\\circ$"},{"key":"C","text":"$71^\\circ$"},{"key":"D","text":"$146^\\circ$"}]$lyceon_json$::jsonb, 'B', NULL, E'The exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Thus the exterior angle at $R$ is $109^\\circ = \\angle P + \\angle Q = 37^\\circ + \\angle Q$, giving $\\angle Q = 109^\\circ - 37^\\circ = 72^\\circ$. The answer $34^\\circ$ results from first finding $\\angle R = 180^\\circ - 109^\\circ = 71^\\circ$ and then subtracting $37^\\circ$ from that. The answer $71^\\circ$ is the interior angle at $R$ itself, not the requested angle $Q$. The answer $146^\\circ$ comes from incorrectly adding $37^\\circ$ to $109^\\circ$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29YB82L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $350$ college students and finds that $42\\%$ regularly use the campus fitness center. The margin of error is $\\pm 3\\%$ at a $95\\%$ confidence level. There are $8{,}400$ students at the college. Based on these results, which of the following is a plausible estimate for the number of students at the college who regularly use the fitness center?', NULL, $lyceon_json$[{"key":"A","text":"$3{,}108$"},{"key":"B","text":"$3{,}528$"},{"key":"C","text":"$3{,}948$"},{"key":"D","text":"$4{,}200$"}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval for the proportion is $42\\% \\pm 3\\%$, or $39\\%$ to $45\\%$. Applying this to $8{,}400$ students gives a plausible range of $0.39 \\times 8{,}400 = 3{,}276$ to $0.45 \\times 8{,}400 = 3{,}780$. The value $3{,}528$ equals $0.42 \\times 8{,}400$, which falls within this range and is the point estimate. The value $3{,}108$ corresponds to $37\\%$, which is outside the confidence interval. The value $3{,}948$ corresponds to $47\\%$, also outside the interval. The value $4{,}200$ is exactly half of $8{,}400$ and does not reflect the survey proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ASIA6B', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line passes through the points $(1, 9)$ and $(4, 21)$. What is the slope of this line?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$12$"},{"key":"D","text":"$-4$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $m = \\frac{21 - 9}{4 - 1} = \\frac{12}{3} = 4$. The value $3$ results from inverting the fraction as $\\frac{3}{12}$ and then simplifying incorrectly. The value $12$ comes from computing only the numerator $21 - 9$ without dividing by the change in $x$. The value $-4$ is a sign error from reversing the order of subtraction in one coordinate but not the other.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ATQW73', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $x^2 - 13x + 22 = 0$ and $x > 10$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Factoring the quadratic: $x^2 - 13x + 22 = (x - 2)(x - 11) = 0$, so $x = 2$ or $x = 11$. Since the problem requires $x > 10$, the answer is $11$. The value $2$ is the other solution but does not satisfy $x > 10$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BWS32P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a slant height of $17$ cm and a base radius of $8$ cm. A plane parallel to the base cuts the cone at a height that is $\\frac{3}{4}$ of the total height from the base, creating a smaller similar cone at the top. What is the volume of the frustum (the portion between the base and the cut), in cubic centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$315\\pi$"},{"key":"B","text":"$320\\pi$"},{"key":"C","text":"$5\\pi$"},{"key":"D","text":"$\\frac{4480\\pi}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'First find the height of the cone: $h = \\sqrt{17^2 - 8^2} = \\sqrt{289 - 64} = \\sqrt{225} = 15$ cm. The volume of the full cone is $V = \\frac{1}{3}\\pi(8)^2(15) = \\frac{960\\pi}{3} = 320\\pi$ cm³. The cut is at $\\frac{3}{4}$ of the height from the base, so the small cone at the top has height $\\frac{1}{4}(15) = \\frac{15}{4}$ cm and radius $\\frac{1}{4}(8) = 2$ cm (by similarity). Its volume is $\\frac{1}{3}\\pi(2)^2\\left(\\frac{15}{4}\\right) = \\frac{1}{3}\\pi(4)\\left(\\frac{15}{4}\\right) = 5\\pi$ cm³. The frustum volume is $320\\pi - 5\\pi = 315\\pi$ cm³. The answer $320\\pi$ is the full cone volume without subtracting the small top cone. The answer $5\\pi$ is only the small cone that was removed, not the frustum. The answer $\\frac{4480\\pi}{3}$ results from using the slant height instead of the actual height in the volume formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DI1RSI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same large population. Sample $X$ includes $150$ individuals and finds that $66\\%$ support a policy change, with a margin of error of $\\pm 5\\%$. Sample $Y$ includes $600$ individuals and finds that $61\\%$ support the same policy change, with a margin of error of $\\pm 2.5\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The results of the two samples contradict each other, so neither is reliable."},{"key":"B","text":"Sample $X$ is more accurate because it found a higher level of support."},{"key":"C","text":"The confidence intervals from the two samples overlap, so the results are consistent with each other."},{"key":"D","text":"Sample $Y$ must contain a systematic bias because it found lower support than Sample $X$."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample $X$ gives a confidence interval of $61\\%$ to $71\\%$, and Sample $Y$ gives a confidence interval of $58.5\\%$ to $63.5\\%$. These intervals overlap (both include values between $61\\%$ and $63.5\\%$), so the two results are consistent with each other and plausibly estimate the same population parameter. The claim that the samples contradict each other ignores the overlap of the intervals. A higher sample statistic does not make a sample more accurate; accuracy depends on sample size and methodology. The claim that Sample $Y$ has systematic bias is unsupported — the difference in point estimates is within the expected range of sampling variability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DOGPUE', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A food truck sells tacos for $\\$4$ each and burritos for $\\$9$ each. The truck needs to earn at least $\\$261$ in revenue per day. If the truck sells $23$ tacos in a day, what is the minimum number of burritos it must sell to meet its daily revenue goal?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$19$"},{"key":"C","text":"$27$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'B', NULL, E'The taco revenue is $23 \\times 4 = 92$ dollars. Setting up the inequality $92 + 9b \\geq 261$ gives $9b \\geq 169$, so $b \\geq 18.\\overline{7}$. Since the truck must sell a whole number of burritos, the minimum is $19$. The value $18$ results from truncating the decimal rather than rounding up to the next whole number. The value $27$ comes from subtracting the number of tacos ($23$) instead of the taco revenue ($92$) from $261$ and then dividing by $9$. The value $29$ comes from ignoring the taco revenue entirely and dividing $261$ by $9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DYQ2ZE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $11, 14, 14, 17, 19, 22, 26$. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$17$"},{"key":"C","text":"$17.57$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $17$. With 7 data values already in ascending order, the median is the 4th value, which is $17$. Choosing $14$ reflects confusion between the mode (the most frequent value) and the median. The value $17.57$ is approximately the mean ($\\frac{123}{7} \\approx 17.57$), confusing mean with median. Choosing $19$ results from selecting the 5th value instead of the 4th, miscounting the middle position.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DZMQQA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $200$ residents in a city found that $118$ support building a new community library. The margin of error for the survey is $\\pm 4\\%$. Which of the following is the best interpretation of the margin of error?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $4\\%$ of the residents were unsure of their response."},{"key":"B","text":"The true percentage of all residents who support the library is between $55\\%$ and $63\\%$."},{"key":"C","text":"The survey included $4\\%$ fewer residents than needed."},{"key":"D","text":"If the survey were repeated, $4\\%$ of respondents would change their answers."}]$lyceon_json$::jsonb, 'B', NULL, E'The sample proportion is $\\frac{118}{200} = 59\\%$. A margin of error of $\\pm 4\\%$ means it is plausible that the true population percentage falls between $59\\% - 4\\% = 55\\%$ and $59\\% + 4\\% = 63\\%$. The statement that $4\\%$ of residents were unsure confuses margin of error with survey nonresponse. The claim about including $4\\%$ fewer residents misinterprets the margin as a sample-size shortfall. The claim about respondents changing answers confuses margin of error with response reliability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EZ4S2Q', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'The equation $y = 1.37x + 18.9$ models the relationship between the number of months since a gym opened ($x$) and its total membership ($y$). According to this model, what is the predicted membership after 23 months?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '50.41', ARRAY['50.41'], E'Substituting $x = 23$ into the equation gives $y = 1.37(23) + 18.9 = 31.51 + 18.9 = 50.41$. A common error is computing $1.37 \\times 23$ incorrectly, such as getting $31.11$ by mishandling the carry, which would yield $50.01$. Another error is interpreting $x$ as the membership rather than months and solving for $x$ instead of evaluating $y$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F00ERX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $4x + 7y = 53$. Line $q$ is perpendicular to line $p$ and passes through the point $(8, -2)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-16', ARRAY['-16'], E'First, find the slope of line $p$ by rewriting in slope-intercept form: $7y = -4x + 53$, so $y = -\\frac{4}{7}x + \\frac{53}{7}$. The slope of line $p$ is $-\\frac{4}{7}$. A line perpendicular to $p$ has slope $\\frac{7}{4}$ (the negative reciprocal). Using point-slope form with $(8, -2)$: $y - (-2) = \\frac{7}{4}(x - 8)$, which gives $y + 2 = \\frac{7}{4}x - 14$, so $y = \\frac{7}{4}x - 16$. The $y$-intercept is $-16$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F74J9Z', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution? $$\\begin{cases} kx - 9y = 22 \\\\ 5x - 3y = 11 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$9$"},{"key":"C","text":"$15$"},{"key":"D","text":"$-15$"}]$lyceon_json$::jsonb, 'C', NULL, E'A system has no solution when the lines are parallel but have different $y$-intercepts. Multiplying the second equation by $3$ gives $15x - 9y = 33$. For the first equation $kx - 9y = 22$ to represent a parallel line, the $x$-coefficients must match: $k = 15$. Since $22 \\neq 33$, the lines are indeed parallel with no intersection. The value $5$ comes from using the $x$-coefficient of the second equation without applying the multiplier needed to match the $y$-coefficients. The value $9$ comes from confusing the $y$-coefficient with the required $x$-coefficient. The value $-15$ introduces a sign error in the proportionality calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FATBF5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has center $(1, -7)$ and passes through the point $(6, 5)$. What is the length of the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The radius is the distance from the center $(1, -7)$ to the point $(6, 5)$. Using the distance formula: $r = \\sqrt{(6-1)^2 + (5-(-7))^2} = \\sqrt{5^2 + 12^2} = \\sqrt{25 + 144} = \\sqrt{169} = 13$. A common error is forgetting to square the differences, computing $5 + 12 = 17$. Another error is subtracting $5 - 7 = -2$ instead of $5 - (-7) = 12$ for the $y$-component, which would give $\\sqrt{25 + 4} = \\sqrt{29}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GFET6J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In the figure, two parallel lines are cut by a transversal. One of the angles formed measures $(3x + 17)^\\circ$ and its co-interior angle (same-side interior angle) measures $(5x - 9)^\\circ$. What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21.5', ARRAY['43/2', '21.5'], E'Co-interior angles (also called consecutive interior angles or same-side interior angles) between parallel lines are supplementary, meaning they sum to $180^\\circ$. Setting up the equation: $(3x + 17) + (5x - 9) = 180$. Combining like terms: $8x + 8 = 180$. Subtracting $8$: $8x = 172$. Dividing by $8$: $x = 21.5$. A common error is setting the angles equal (as if they were alternate interior angles), which would give $2x = 26$, so $x = 13$. Another error is forgetting to combine the constant terms correctly, leading to $8x = 188$ and $x = 23.5$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HSHS2U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'The population of a town was $8{,}370$ in 2020. By 2023, the population had increased to $9{,}621$. To the nearest tenth of a percent, what was the percent increase in the town''s population from 2020 to 2023?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14.9', ARRAY['14.9'], E'The percent increase is $\\frac{9621 - 8370}{8370} \\times 100 = \\frac{1251}{8370} \\times 100 \\approx 14.946\\%$, which rounds to $14.9\\%$. A common error is dividing the change by the new population: $\\frac{1251}{9621} \\times 100 \\approx 13.0\\%$. Another error is computing $\\frac{9621}{8370} = 1.1495$ and reporting $1.1$ or $11.5$ instead of recognizing that the percent increase is approximately $14.9$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IMWHTP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $7$ and $11$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{170}$"},{"key":"B","text":"$\\sqrt{130}$"},{"key":"C","text":"$18$"},{"key":"D","text":"$\\sqrt{72}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 7^2 + 11^2 = 49 + 121 = 170$, so $c = \\sqrt{170}$. The answer $\\sqrt{130}$ results from computing $49 + 81$ (squaring $9$ instead of $11$). The answer $18$ comes from simply adding the two legs rather than applying the Pythagorean theorem. The answer $\\sqrt{72}$ comes from subtracting the squares ($121 - 49 = 72$) instead of adding them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JFIYUZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The equation $a(3x + 7) = 6x + b$ has infinitely many solutions. Which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"$a = 2$ and $b = 14$"},{"key":"B","text":"$a = 2$ and $b = 7$"},{"key":"C","text":"$a = 3$ and $b = 7$"},{"key":"D","text":"$a = 6$ and $b = 42$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the equation to have infinitely many solutions, the left side must be identical to the right side. Expanding: $3ax + 7a = 6x + b$. Matching coefficients of $x$: $3a = 6$, so $a = 2$. Matching constants: $7a = b$, so $b = 7(2) = 14$. The pair $a = 2$ and $b = 7$ correctly identifies $a$ but fails to compute $b = 7a$, instead using $b = 7$ without the multiplication. The pair $a = 3$ and $b = 7$ confuses the coefficient of $x$ inside the parentheses with the required value of $a$. The pair $a = 6$ and $b = 42$ sets $a$ equal to the coefficient on the right side rather than solving $3a = 6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JRP62B', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'A population of bacteria triples every hour. If there are $7$ bacteria at hour $0$, how many bacteria are there at hour $3$?', NULL, $lyceon_json$[{"key":"A","text":"$189$"},{"key":"B","text":"$63$"},{"key":"C","text":"$21$"},{"key":"D","text":"$343$"}]$lyceon_json$::jsonb, 'A', NULL, E'The population follows the exponential model $P(t) = 7 \\cdot 3^t$. At $t = 3$, $P(3) = 7 \\cdot 3^3 = 7 \\cdot 27 = 189$. The value $63$ comes from computing $7 \\cdot 3^2 = 63$, which represents only $2$ hours of growth instead of $3$. The value $21$ results from multiplying $7 \\cdot 3 = 21$, treating the growth as a single tripling rather than three successive triplings. The value $343$ comes from computing $7^3 = 343$, raising the initial population to the power of the time instead of raising the growth factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JVJANW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$ inches. What is the circumference of the circle, in inches?', NULL, $lyceon_json$[{"key":"A","text":"$26\\pi$"},{"key":"B","text":"$13\\pi$"},{"key":"C","text":"$169\\pi$"},{"key":"D","text":"$676\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Thus $C = 26\\pi$ inches. The answer $13\\pi$ results from using the radius ($13$) in the formula $C = \\pi r$ instead of $C = 2\\pi r$ or $C = \\pi d$. The answer $169\\pi$ comes from computing the area formula $\\pi r^2 = \\pi(13)^2 = 169\\pi$, confusing area with circumference. The answer $676\\pi$ uses $\\pi d^2$ instead of $\\pi d$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K1OPP3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A teacher recorded the following quiz scores for 9 students: $53, 67, 71, 71, 74, 78, 82, 85, 91$. If an additional student scores $99$ on the quiz, what is the median score for all 10 students?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '76', ARRAY['76'], E'With the original 9 scores in order and the new score of $99$ appended, the 10 ordered scores are $53, 67, 71, 71, 74, 78, 82, 85, 91, 99$. For an even number of values, the median is the average of the 5th and 6th values: $\\frac{74 + 78}{2} = \\frac{152}{2} = 76$. A common error is taking only the 5th value ($74$) or the 6th value ($78$) without averaging. Another error is recalculating the mean instead of the median.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M1JA8G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher recruited $120$ students who volunteered from an introductory psychology course to study whether listening to classical music while studying improves exam scores. She randomly assigned $60$ students to study with classical music and $60$ to study in silence. The classical music group scored an average of $7$ points higher on the exam. Which of the following is the most significant limitation of the study''s design?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $120$ is too small to detect a meaningful difference."},{"key":"B","text":"The researcher did not use a placebo, so the results could be influenced by the participants' expectations."},{"key":"C","text":"Because the participants were volunteers from a single course, the results may not generalize to all college students."},{"key":"D","text":"Random assignment was not used, so confounding variables may explain the difference."}]$lyceon_json$::jsonb, 'C', NULL, E'The most significant limitation is that the sample was drawn from volunteers in a single introductory psychology course, which is a convenience sample rather than a random sample of all college students. This limits the generalizability of the findings. A sample of $120$ with $60$ per group is generally adequate to detect a $7$-point difference, so sample size is not the primary concern. While a placebo consideration has some merit, the study does have a control condition (silence), and the lack of blinding is a secondary issue compared to the sampling bias. The claim that random assignment was not used is factually incorrect — the stem states that the researcher randomly assigned participants to groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N2SEZ8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher finds that cities with more public swimming pools per capita tend to have higher rates of sunburn-related emergency room visits. Which of the following is the most appropriate conclusion based on this finding?', NULL, $lyceon_json$[{"key":"A","text":"Building more swimming pools causes an increase in sunburn-related emergency room visits."},{"key":"B","text":"Reducing the number of swimming pools would decrease sunburn-related emergency room visits."},{"key":"C","text":"There is an association between the number of swimming pools per capita and sunburn-related emergency room visits, but a causal relationship cannot be established."},{"key":"D","text":"Swimming pools are a health hazard and should be regulated to reduce sunburn."}]$lyceon_json$::jsonb, 'C', NULL, E'This is an observational finding showing a correlation between two variables. Because no random assignment or controlled experiment was conducted, a causal conclusion cannot be drawn. A confounding variable, such as climate or sun exposure, could explain both the prevalence of pools and the rate of sunburns. The claim that building pools causes more sunburns asserts causation from correlation. The suggestion that reducing pools would decrease sunburns similarly assumes a causal link. The claim that pools are a health hazard goes beyond what the data support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NIIPFB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of 20 values has a mean of $34.7$ and a median of $31$. Each value in the data set is multiplied by $3$ and then $8$ is added to the result. Which of the following gives the new mean and the new median, respectively?', NULL, $lyceon_json$[{"key":"A","text":"Mean: $112.1$; Median: $101$"},{"key":"B","text":"Mean: $104.1$; Median: $93$"},{"key":"C","text":"Mean: $112.1$; Median: $93$"},{"key":"D","text":"Mean: $104.1$; Median: $101$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is Mean: $112.1$ and Median: $101$. When each value $x$ is transformed to $3x + 8$, both the mean and median undergo the same linear transformation. The new mean is $3(34.7) + 8 = 104.1 + 8 = 112.1$ and the new median is $3(31) + 8 = 93 + 8 = 101$. The pair with mean $104.1$ and median $93$ results from multiplying by 3 but forgetting to add 8 to both statistics. The pair with mean $112.1$ and median $93$ correctly transforms the mean but forgets to add 8 to the median. The pair with mean $104.1$ and median $101$ adds 8 to the median but forgets to add 8 to the mean.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OBL1OD', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{4x^2 + 11x - 7}{x + 3} = ax + b + \\frac{c}{x + 3}$ for all $x \\neq -3$, what is the value of $a + b + c$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Performing polynomial long division of $4x^2 + 11x - 7$ by $x + 3$: dividing $4x^2$ by $x$ gives $4x$, and $4x(x + 3) = 4x^2 + 12x$. Subtracting from $4x^2 + 11x - 7$ yields $-x - 7$. Dividing $-x$ by $x$ gives $-1$, and $-1(x + 3) = -x - 3$. Subtracting from $-x - 7$ yields $-4$. Therefore $a = 4$, $b = -1$, $c = -4$, and $a + b + c = 4 + (-1) + (-4) = -1$. The value $1$ results from a sign error when determining $b$, using $b = 1$ instead of $b = -1$. The value $3$ comes from computing only $a + b = 4 + (-1) = 3$ and omitting the remainder $c$. The value $7$ results from an arithmetic error of using $c = 4$ instead of $c = -4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P7UWVH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'For what value of $k$ does the system of equations $y = x^2 + 6x + k$ and $y = 2x - 3$ have exactly one solution?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$4$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 + 6x + k = 2x - 3$, which simplifies to $x^2 + 4x + (k + 3) = 0$. For exactly one solution, the discriminant must equal zero: $16 - 4(k + 3) = 0$, giving $16 - 4k - 12 = 0$, so $4 = 4k$ and $k = 1$. The value $-1$ results from a sign error in the final step. The value $4$ comes from setting $16 - 4k = 0$ without including the constant $+3$ that arises from rearranging. The value $7$ results from incorrectly rearranging the constant as $k - 3$ instead of $k + 3$, leading to $16 - 4(k - 3) = 0$ and $k = 7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P81Z9A', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A plumber charges a flat fee of 47 dollars for a service call plus 31 dollars per hour of labor. Which function $f(h)$ gives the total charge, in dollars, for $h$ hours of labor?', NULL, $lyceon_json$[{"key":"A","text":"$f(h) = 31h + 47$"},{"key":"B","text":"$f(h) = 47h + 31$"},{"key":"C","text":"$f(h) = 78h$"},{"key":"D","text":"$f(h) = (31 + 47)h$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total charge is the flat fee of 47 dollars plus 31 dollars for each hour, giving $f(h) = 31h + 47$. The function $f(h) = 47h + 31$ reverses the roles of the flat fee and the hourly rate. The function $f(h) = 78h$ adds the two values together and treats the sum as a single hourly rate, ignoring that 47 dollars is a fixed cost. Similarly, $f(h) = (31 + 47)h$ makes the same error in factored form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGSS2E', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the solution $(x, y)$ to the following system of equations? $$\\begin{cases} x + 3y = 31 \\\\ x = 4 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$(4, 9)$"},{"key":"B","text":"$(4, 27)$"},{"key":"C","text":"$(31, 4)$"},{"key":"D","text":"$(4, -9)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 4$ into the first equation gives $4 + 3y = 31$, so $3y = 27$ and $y = 9$. The solution is $(4, 9)$. The pair $(4, 27)$ results from computing $31 - 4 = 27$ but omitting the division by $3$. The pair $(31, 4)$ swaps the $x$ and $y$ coordinates. The pair $(4, -9)$ introduces a sign error when solving for $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PNJLUJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A jar contains $41$ tokens: $17$ are red, $13$ are blue, and $11$ are green. Two tokens are drawn at random without replacement. What is the probability that both tokens drawn are blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{41} \\cdot \\frac{13}{41}$"},{"key":"B","text":"$\\frac{13}{41} \\cdot \\frac{12}{40}$"},{"key":"C","text":"$\\frac{13}{41} \\cdot \\frac{12}{41}$"},{"key":"D","text":"$\\frac{26}{82}$"}]$lyceon_json$::jsonb, 'B', NULL, E'When drawing without replacement, the probability that the first token is blue is $\\frac{13}{41}$. After removing one blue token, $12$ blue tokens remain out of $40$ total, so the probability the second is also blue is $\\frac{12}{40}$. The combined probability is $\\frac{13}{41} \\cdot \\frac{12}{40}$. The expression $\\frac{13}{41} \\cdot \\frac{13}{41}$ incorrectly treats the draws as independent (with replacement). The expression $\\frac{13}{41} \\cdot \\frac{12}{41}$ reduces the numerator but forgets to reduce the denominator after the first draw. The expression $\\frac{26}{82}$ attempts to double both the numerator and denominator of a single draw, which does not model two sequential draws.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PU22FS', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -\\frac{5}{3}x + 22$. For what value of $x$ does $g(x) = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$\\frac{87}{5}$"},{"key":"D","text":"$\\frac{29}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set $g(x) = 7$: $-\\frac{5}{3}x + 22 = 7$. Subtract $22$: $-\\frac{5}{3}x = -15$. Multiply both sides by $-\\frac{3}{5}$: $x = -15 \\cdot (-\\frac{3}{5}) = 9$. The value $-9$ comes from a sign error when multiplying two negatives. The value $\\frac{87}{5}$ results from incorrectly adding $7$ and $22$ instead of subtracting, then dividing by $\\frac{5}{3}$. The value $\\frac{29}{5}$ comes from an arithmetic error in simplifying the final division.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PUP3BA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $p(2) = 54$ and $p(5) = 1458$, what is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$27$"},{"key":"C","text":"$6$"},{"key":"D","text":"$\\frac{1}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'From $p(2) = ab^2 = 54$ and $p(5) = ab^5 = 1458$, dividing the second equation by the first eliminates $a$: $\\frac{ab^5}{ab^2} = \\frac{1458}{54}$, so $b^3 = 27$. Taking the cube root gives $b = 3$. The value $27$ results from correctly finding $b^3 = 27$ but reporting $b^3$ rather than $b$ itself. The value $6$ results from an error in setting up the equations, such as solving $ab^2 = 54$ with an incorrect assumption about $a$ and confusing the resulting value with $b$. The value $\\frac{1}{3}$ results from inverting the division ratio, computing $\\frac{p(2)}{p(5)} = \\frac{1}{27}$ and then taking $b^3 = \\frac{1}{27}$, yielding $b = \\frac{1}{3}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PW7XKH', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $f$ is linear, and the table below shows selected values.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q4N356', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A ladder leans against a vertical wall so that the top of the ladder is $19$ feet above the ground. The ladder makes an angle of $67^\\circ$ with the ground. What is the length of the ladder, in feet, rounded to the nearest tenth? (Use $\\sin 67^\\circ \\approx 0.9205$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '20.6', ARRAY['103/5', '20.6'], E'The height where the ladder meets the wall ($19$ feet) is the side opposite the $67^\\circ$ angle, and the ladder itself is the hypotenuse. Using $\\sin(67^\\circ) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{19}{L}$, we get $L = \\frac{19}{\\sin(67^\\circ)} = \\frac{19}{0.9205} \\approx 20.6$ feet. A common error is using cosine instead of sine, giving $\\frac{19}{0.3907} \\approx 48.6$. Another error is multiplying $19 \\times 0.9205 \\approx 17.5$ instead of dividing.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QZVPZC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A ceramicist uses $\\frac{7}{4}$ pounds of clay to produce 3 identical bowls. At this rate, how many pounds of clay are needed to produce 12 bowls?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{21}{4}$"},{"key":"D","text":"$\\frac{48}{7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $7$. The rate is $\\frac{7}{4}$ pounds per 3 bowls. For 12 bowls, which is $12 \\div 3 = 4$ groups of 3, the clay needed is $4 \\times \\frac{7}{4} = 7$ pounds. The result $\\frac{21}{4}$ comes from multiplying $\\frac{7}{4}$ by 3 instead of 4, confusing the multiplier. The result $\\frac{48}{7}$ arises from setting up the proportion incorrectly by dividing 12 by $\\frac{7}{4}$. The result $5$ comes from an arithmetic error in the multiplication.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RR7LGW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $xy = 35$ and $x + y = 12$, what is the value of $x^2 + y^2$?', NULL, $lyceon_json$[{"key":"A","text":"$74$"},{"key":"B","text":"$144$"},{"key":"C","text":"$109$"},{"key":"D","text":"$214$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the algebraic identity $x^2 + y^2 = (x + y)^2 - 2xy$, substitute the given values: $x^2 + y^2 = 12^2 - 2(35) = 144 - 70 = 74$. This can be verified: $x$ and $y$ are roots of $t^2 - 12t + 35 = 0$, so $(t - 5)(t - 7) = 0$, and indeed $5^2 + 7^2 = 25 + 49 = 74$. The value $144$ results from computing $(x + y)^2$ but neglecting to subtract $2xy$. The value $109$ comes from subtracting $xy = 35$ only once instead of $2xy = 70$, yielding $144 - 35 = 109$. The value $214$ results from adding $2xy$ instead of subtracting it, computing $(x + y)^2 + 2xy = 144 + 70 = 214$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RYVZL0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylindrical water tank has a radius of $4$ feet and a height of $11$ feet. What is the volume of the tank, in cubic feet? (Give your answer as the coefficient of $\\pi$; that is, if the volume is $k\\pi$, enter $k$.)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '176', ARRAY['176'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting $r = 4$ and $h = 11$: $V = \\pi (4)^2 (11) = \\pi (16)(11) = 176\\pi$ cubic feet. The coefficient of $\\pi$ is $176$. A common error is using the diameter instead of the radius, giving $\\pi(8)^2(11) = 704\\pi$. Another error is computing $\\pi r h$ instead of $\\pi r^2 h$, which gives $44\\pi$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S0CPH0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer marks up wholesale goods by $45\\%$ to set the retail price. During a clearance event, all retail prices are discounted by $28\\%$. A customer also has a loyalty coupon for an additional $10\\%$ off the already-discounted price. If a product''s wholesale cost is $\\$62$, what does the customer pay, rounded to the nearest cent?', NULL, $lyceon_json$[{"key":"A","text":"$\\$58.26$"},{"key":"B","text":"$\\$55.75$"},{"key":"C","text":"$\\$46.30$"},{"key":"D","text":"$\\$64.73$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\$58.26$. The retail price is $62 \\times 1.45 = \\$89.90$. After the $28\\%$ clearance discount, the price becomes $89.90 \\times 0.72 = \\$64.728$. After the additional $10\\%$ loyalty discount on the discounted price, the customer pays $64.728 \\times 0.90 = \\$58.2552$, which rounds to $\\$58.26$. The result $\\$55.75$ comes from applying the $28\\%$ discount to the retail price but then applying $10\\%$ off the wholesale cost instead of the discounted price. The result $\\$46.30$ comes from incorrectly adding the discount percentages ($28\\% + 10\\% = 38\\%$) and then subtracting $38\\%$ from the wholesale cost rather than applying sequential discounts to the marked-up price. The result $\\$64.73$ comes from applying only the clearance discount and omitting the loyalty coupon.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SDR6D1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $5x - 3y = 39$ represents a line in the $xy$-plane. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -13)$"},{"key":"B","text":"$(0, 13)$"},{"key":"C","text":"$(0, -39)$"},{"key":"D","text":"$(0, \\frac{39}{5})$"}]$lyceon_json$::jsonb, 'A', NULL, E'To find the $y$-intercept, set $x = 0$: $5(0) - 3y = 39$, which gives $-3y = 39$, so $y = -13$. The $y$-intercept is $(0, -13)$. The answer $(0, 13)$ results from dropping the negative sign when dividing $39$ by $-3$. The answer $(0, -39)$ treats the constant term as the $y$-intercept without dividing by the coefficient of $y$. The answer $(0, \\frac{39}{5})$ finds the $x$-intercept instead of the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T27TRL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of 40 adults. The least-squares regression line is $\\hat{y} = -0.29x + 87.4$, with a coefficient of determination $r^2 = 0.63$. One individual is 55 years old and has a resting heart rate of 68 beats per minute. What is the residual for this individual, and what does the $r^2$ value indicate about the model?', NULL, $lyceon_json$[{"key":"A","text":"Residual: $-3.45$; $63\\%$ of the variation in resting heart rate is explained by age."},{"key":"B","text":"Residual: $3.45$; $63\\%$ of the variation in resting heart rate is explained by age."},{"key":"C","text":"Residual: $-3.45$; $63\\%$ of the variation in age is explained by resting heart rate."},{"key":"D","text":"Residual: $3.45$; the correlation between age and heart rate is $0.63$."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer has a residual of $-3.45$ and states that $63\\%$ of the variation in resting heart rate is explained by age. The predicted value is $\\hat{y} = -0.29(55) + 87.4 = -15.95 + 87.4 = 71.45$. The residual is observed minus predicted: $68 - 71.45 = -3.45$, meaning the actual heart rate is $3.45$ beats per minute below the prediction. The coefficient $r^2 = 0.63$ means $63\\%$ of the variation in the response variable (resting heart rate) is accounted for by the linear relationship with age. The choice with residual $3.45$ reverses the subtraction order, computing predicted minus observed. The choice stating $63\\%$ of variation in age is explained swaps the explanatory and response variables. The choice equating $r^2$ directly with the correlation confuses the coefficient of determination with the correlation coefficient $r$ (which would be $\\sqrt{0.63} \\approx 0.794$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UL8U08', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours spent practicing piano each week and the number of errors made during a recital. The line of best fit for the data is $y = -4.3x + 51.6$, where $x$ is hours practiced and $y$ is the predicted number of errors. What does the slope of the line of best fit indicate?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of practice, the predicted number of errors decreases by $4.3$."},{"key":"B","text":"For each additional hour of practice, the predicted number of errors increases by $4.3$."},{"key":"C","text":"A student who does not practice is predicted to make $51.6$ errors."},{"key":"D","text":"For each additional error, the number of practice hours decreases by $4.3$."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is that for each additional hour of practice, the predicted number of errors decreases by $4.3$. The slope of $-4.3$ means that for every one-unit increase in $x$ (hours practiced), $y$ (predicted errors) decreases by $4.3$. The choice stating errors increase by $4.3$ ignores the negative sign of the slope. The choice about $51.6$ errors describes the $y$-intercept, not the slope, and does not answer what the slope indicates. The choice reversing the variables confuses the independent variable with the dependent variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2URXQQ8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A printer produces 47 pages in 2 minutes. A second printer produces 29 pages per minute. Working together simultaneously, how many pages do the two printers produce in 11 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '577.5', ARRAY['577.5'], E'The first printer produces pages at a rate of $\\frac{47}{2} = 23.5$ pages per minute. The second printer produces $29$ pages per minute. Together, they produce $23.5 + 29 = 52.5$ pages per minute. In 11 minutes, they produce $52.5 \\times 11 = 577.5$ pages. A common error is rounding the first printer''s rate to 24, which would give $53 \\times 11 = 583$. Another error is treating 47 as a per-minute rate, giving $(47 + 29) \\times 11 = 836$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VW1RKT', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $-11x \\leq 77$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq -7$"},{"key":"B","text":"$x \\geq -7$"},{"key":"C","text":"$x \\geq 7$"},{"key":"D","text":"$x \\leq 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Dividing both sides of $-11x \\leq 77$ by $-11$ and reversing the inequality sign gives $x \\geq -7$. The choice $x \\leq -7$ results from forgetting to flip the inequality when dividing by a negative number. The choice $x \\geq 7$ comes from dividing correctly but dropping the negative sign on the result. The choice $x \\leq 7$ combines both errors, arriving at the wrong sign and wrong direction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W7EO9G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A shelf at a ceramics studio holds $37$ finished pieces: $14$ are bowls, $9$ are vases, and $14$ are mugs. If one piece is selected at random from the shelf, what is the probability that it is a vase?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{37}$"},{"key":"B","text":"$\\frac{14}{37}$"},{"key":"C","text":"$\\frac{9}{28}$"},{"key":"D","text":"$\\frac{9}{23}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The probability of selecting a vase is the number of vases divided by the total number of pieces: $\\frac{9}{37}$. The answer $\\frac{14}{37}$ results from selecting the count for bowls or mugs instead of vases. The answer $\\frac{9}{28}$ comes from incorrectly subtracting the vases from the total and using $28$ as the denominator. The answer $\\frac{9}{23}$ results from using only the sum of the other two categories ($14 + 9 = 23$) as the denominator instead of the full total.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YD6TZI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore sells a novel for $\\$23$. During a sale, the price is reduced by $30\\%$. What is the sale price of the novel?', NULL, $lyceon_json$[{"key":"A","text":"$\\$16.10$"},{"key":"B","text":"$\\$6.90$"},{"key":"C","text":"$\\$19.30$"},{"key":"D","text":"$\\$17.10$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\$16.10$. A $30\\%$ reduction means the discount is $0.30 \\times 23 = \\$6.90$, so the sale price is $23 - 6.90 = \\$16.10$. Equivalently, the sale price is $23 \\times 0.70 = \\$16.10$. The result $\\$6.90$ gives the discount amount rather than the sale price, misreading what the question asks. The result $\\$19.30$ comes from computing $23 - 3.70$, perhaps confusing $30\\%$ with subtracting $\\$3.70$. The result $\\$17.10$ arises from a faulty calculation such as $23 \\times 0.26$ or other arithmetic confusion with the percentage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YZV8XN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The quadratic function $g$ is defined by $g(x) = -2(x - 4)^2 + 13$. Which of the following statements about $g$ is true?', NULL, $lyceon_json$[{"key":"A","text":"The function $g$ has a maximum value of $13$."},{"key":"B","text":"The function $g$ has a minimum value of $13$."},{"key":"C","text":"The function $g$ has a maximum value of $4$."},{"key":"D","text":"The function $g$ has a minimum value of $-13$."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the leading coefficient is $-2$ (negative), the parabola opens downward, so $g$ has a maximum value. In vertex form $g(x) = -2(x - 4)^2 + 13$, the vertex is at $(4, 13)$, so the maximum value of $g$ is $13$. Stating that $g$ has a minimum value of $13$ reflects a misunderstanding of how the sign of the leading coefficient determines whether the vertex is a maximum or minimum. Claiming the maximum is $4$ confuses the $x$-coordinate of the vertex with the function''s extreme value. Stating the minimum is $-13$ combines a sign error on the vertex''s $y$-coordinate with the incorrect direction of the parabola.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZBU73H', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $5(3x^2 - 2x) + 7x$?', NULL, $lyceon_json$[{"key":"A","text":"$15x^2 - 3x$"},{"key":"B","text":"$15x^2 + 3x$"},{"key":"C","text":"$15x^2 - 10x$"},{"key":"D","text":"$15x^2 + 7x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the 5 gives $15x^2 - 10x$. Adding $7x$ yields $15x^2 - 10x + 7x = 15x^2 - 3x$. The distractor $15x^2 + 3x$ results from a sign error when combining $-10x + 7x$. The distractor $15x^2 - 10x$ forgets to add the $7x$ term. The distractor $15x^2 + 7x$ fails to combine the $x$ terms properly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZLOMPR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{4(2x - 5)}{3} + 6 = 18$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Subtracting 6 from both sides gives $\\frac{4(2x - 5)}{3} = 12$. Multiplying both sides by 3 gives $4(2x - 5) = 36$. Dividing both sides by 4 gives $2x - 5 = 9$. Adding 5 to both sides gives $2x = 14$, so $x = 7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2095UNN', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the fourteen monitoring stations installed along the river _______ equipped with sensors that record water temperature, dissolved oxygen levels, and current velocity every thirty minutes.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were being"},{"key":"D","text":"are being"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "each," which is grammatically singular regardless of the prepositional phrase "of the fourteen monitoring stations" that follows it. The singular present-tense verb "is" correctly agrees with "each." The plural verb "are" incorrectly treats "stations" as the subject. "Were being" is both plural in implication and shifts to a past progressive tense that conflicts with the present-tense verb "record" later in the sentence. "Are being" uses a plural form that does not agree with the singular subject "each."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20KJQR0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "plastic" most nearly means', E'Neuroscientists studying barn owls discovered that the auditory localization circuits in juvenile owls are remarkably plastic: when researchers fitted young owls with prismatic lenses that shifted their visual field by 23 degrees, the birds gradually recalibrated their sound-localization maps to match the altered visual input. Adult owls fitted with the same lenses showed no such recalibration.', $lyceon_json$[{"key":"A","text":"synthetic"},{"key":"B","text":"rigid"},{"key":"C","text":"adaptable"},{"key":"D","text":"transparent"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes neural circuits that can recalibrate in response to altered sensory input, so "adaptable" captures the intended meaning. "Synthetic" refers to artificial materials, which is a common meaning of "plastic" but has no connection to neural development. "Rigid" contradicts the passage, which emphasizes the capacity for change. "Transparent" describes visibility rather than flexibility and does not relate to the circuits'' ability to reorganize.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
