INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28ES4Y8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Zurich recently demonstrated that certain alpine mosses can survive prolonged desiccation by entering a state of metabolic dormancy. When deprived of water for up to nineteen months, these mosses ceased nearly all cellular activity yet retained the structural integrity of their chloroplasts. Upon rehydration, the mosses resumed photosynthesis within seventy-two hours, achieving rates comparable to those measured before desiccation. The findings suggest that alpine mosses possess biochemical mechanisms that protect cellular components during extreme water loss.', $lyceon_json$[{"key":"A","text":"Alpine mosses can endure extended periods without water by becoming dormant and then quickly recovering their photosynthetic function."},{"key":"B","text":"The chloroplasts of alpine mosses are structurally different from those of mosses found at lower elevations."},{"key":"C","text":"Researchers at the University of Zurich were the first to study the effects of desiccation on plant cells."},{"key":"D","text":"Alpine mosses are the most resilient plant species found in mountainous environments worldwide."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centrally describes how alpine mosses survive long desiccation by entering dormancy and then resuming photosynthesis upon rehydration, making the choice about enduring water loss through dormancy and recovering photosynthetic function the best statement of the main idea. The choice about chloroplast structural differences misreads the passage, which states the chloroplasts retained integrity rather than claiming they differ from those of other mosses. The choice about the University of Zurich being the first to study desiccation overstates what the passage says; it mentions only that these researchers demonstrated the phenomenon, not that they were the first. The choice claiming alpine mosses are the most resilient species worldwide goes beyond anything the passage states.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28ZHDTF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'As of this quarter, neither the governor''s proposed tax incentive nor the legislature''s amended version of the _______ expected to generate sufficient revenue to offset the projected budget deficit.', $lyceon_json$[{"key":"A","text":"bill have been"},{"key":"B","text":"bill is"},{"key":"C","text":"bill are"},{"key":"D","text":"bill were"}]$lyceon_json$::jsonb, 'B', NULL, E'With the correlative conjunction "neither...nor," the verb must agree in number with the nearer subject. The nearer subject is "the legislature''s amended version of the bill," which is singular, so the singular verb "is" is required. The phrase "as of this quarter" establishes the present tense. "Have been" is plural and does not agree with the singular nearer subject. "Are" is also plural. "Were" is past tense, which conflicts with the present time frame established by "as of this quarter."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
