INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29IZ4CV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Volcanic glass, known as obsidian, forms when lava cools too rapidly for crystal structures to _______ the resulting material is prized by archaeologists because its chemical composition can be traced to specific volcanic sources.', $lyceon_json$[{"key":"A","text":"develop, the"},{"key":"B","text":"develop; the"},{"key":"C","text":"develop the"},{"key":"D","text":"develop; and the"}]$lyceon_json$::jsonb, 'B', NULL, E'Two independent clauses appear here: one about how obsidian forms and one about why the resulting material is valued by archaeologists. A semicolon correctly joins two closely related independent clauses. Using only a comma between them creates a comma splice, which is a boundary error. Omitting all punctuation produces a fused sentence. Placing a semicolon before a coordinating conjunction ("and") is non-standard and incorrect because the semicolon already functions as the clause connector, making the conjunction redundant.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AL48MM', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the reference to "the Ptolemaic model" in the passage?', E'When scientists encounter data that contradicts a well-established framework, they rarely abandon the framework immediately. Instead, they typically introduce auxiliary hypotheses to reconcile the anomalous findings with the existing theory. The Ptolemaic model of the solar system, for instance, survived for over a millennium partly because astronomers continually added epicycles to account for observed planetary motions that deviated from the model''s predictions. Only when an alternative framework emerges that explains both the established data and the anomalies more parsimoniously does a paradigm shift become possible.', $lyceon_json$[{"key":"A","text":"It provides a specific historical case that illustrates the general pattern of preserving established frameworks through supplementary modifications."},{"key":"B","text":"It introduces a counterexample that undermines the passage's claim about how scientists respond to contradictory evidence."},{"key":"C","text":"It demonstrates that ancient scientific models were inherently less reliable than modern ones."},{"key":"D","text":"It argues that the Ptolemaic model was ultimately vindicated by later astronomical discoveries."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage introduces the Ptolemaic model with the phrase "for instance," signaling that it serves as a concrete historical example of the general pattern described in the preceding sentences: scientists add auxiliary hypotheses (epicycles) to preserve an established framework rather than abandoning it. The Ptolemaic reference supports rather than undermines the passage''s claim, so calling it a counterexample mischaracterizes its rhetorical role. The passage does not compare ancient and modern models in terms of reliability. The passage notes the Ptolemaic model eventually gave way to a more parsimonious alternative, directly contradicting the idea that it was vindicated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AWCU78', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the second sentence in the passage?', E'Coral reefs occupy less than one percent of the ocean floor. Yet these structures support roughly one quarter of all known marine species, providing habitat for an estimated 4,000 species of fish alone.', $lyceon_json$[{"key":"A","text":"It introduces a contrast that highlights the ecological significance of coral reefs."},{"key":"B","text":"It provides a historical account of how coral reefs developed over time."},{"key":"C","text":"It questions the accuracy of scientific measurements of ocean habitats."},{"key":"D","text":"It proposes a method for expanding coral reef coverage in the ocean."}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence uses "Yet" to pivot from the small physical extent described in the first sentence to the outsized biological importance of coral reefs, establishing a contrast that underscores their ecological significance. The sentence contains no historical information about reef development, so the historical account option is unsupported. The passage presents the data as factual rather than questioning scientific measurements. No method for expanding reef coverage is proposed anywhere in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BO348Y', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'In 1847, the Hungarian physician Ignaz Semmelweis noticed that the maternal mortality rate in the division staffed by medical students was three times higher than in the division staffed by midwives. He hypothesized that the students, who routinely performed autopsies before delivering babies, were transferring "cadaverous particles" to the mothers. When Semmelweis instituted a policy requiring hand-washing with chlorinated lime solution, the mortality rate in the students'' division fell from 18 percent to under 2 percent within three months. Despite this dramatic result, the broader medical establishment dismissed his findings, and widespread adoption of antiseptic practices did not occur until decades later.', $lyceon_json$[{"key":"A","text":"It presents an observation, proposes an explanation, describes the outcome of a resulting intervention, and notes the delayed reception of the findings."},{"key":"B","text":"It compares two competing medical theories and evaluates which theory has stronger empirical support."},{"key":"C","text":"It narrates a physician's career from medical school through retirement, emphasizing personal achievements."},{"key":"D","text":"It argues that modern medical practices are superior to those of the nineteenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage follows a clear sequence: Semmelweis observes a mortality discrepancy, hypothesizes a cause involving cadaverous particles, implements hand-washing with dramatic results, and then faces rejection from the medical community. This matches the description of observation, explanation, intervention outcome, and delayed reception. The passage does not present two competing theories or evaluate their relative merit. It covers a single episode in Semmelweis''s career, not a full career narrative. The passage describes a historical event rather than making an argument about the superiority of modern practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
