INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ELMWLW', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research study, if accurate, would most effectively support the literary scholar''s argument?', E'Literary scholar Priya Chandran has argued that the rise of serialized fiction in nineteenth-century Indian newspapers did not merely reflect existing reader demand but actively shaped new reading habits among middle-class Bengali households. Chandran contends that the weekly installment format created a ritualized pattern of family reading sessions that had no precedent in earlier Bengali literary culture. She further argues that this shift in reading practice contributed to the emergence of a distinctly modern Bengali literary public sphere, one organized around periodical consumption rather than the patronage networks that had previously sustained literary production.', $lyceon_json$[{"key":"A","text":"\"Surveys of household routines in Calcutta between 1870 and 1895 reveal that families subscribing to serialized fiction periodicals were three times more likely to report weekly communal reading gatherings than families without such subscriptions, and these gatherings had no documented equivalent in the pre-periodical era.\""},{"key":"B","text":"\"Bengali novelists writing between 1860 and 1900 frequently acknowledged the influence of English serialized fiction on their narrative techniques, particularly the use of cliffhanger chapter endings.\""},{"key":"C","text":"\"Subscription rates for Bengali literary periodicals increased by 40 percent between 1875 and 1890, suggesting growing literacy among the urban middle class during this period.\""},{"key":"D","text":"\"An analysis of publisher records from the 1880s shows that Bengali novels published in single volumes outsold serialized editions by a ratio of approximately two to one.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Chandran argues that serialized fiction created new ritualized family reading sessions without precedent in earlier Bengali culture. The quotation about surveys showing subscribers were three times more likely to hold weekly communal reading gatherings with no pre-periodical equivalent directly supports both the claim of new reading habits and their lack of precedent. The quotation about English serialized fiction influencing narrative techniques addresses literary technique rather than reading habits in households. The quotation about rising subscription rates shows growing readership but does not demonstrate that new reading practices were formed or that they lacked precedent. The quotation about single-volume novels outselling serialized editions would actually undermine the argument by suggesting serialization was less dominant than Chandran implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EMFM3X', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "economy" most nearly means', E'Literary scholars have noted the striking economy of Matsuo Basho''s later haiku, composed during his final journeys through northern Japan in the 1690s. Where his earlier verses occasionally relied on elaborate conceits or cultural allusions that demanded annotation, the mature poems achieve their resonance through the sparest possible arrangement of concrete images, each syllable bearing the weight that entire stanzas carried in his youth.', $lyceon_json$[{"key":"A","text":"financial arrangement"},{"key":"B","text":"deliberate restraint"},{"key":"C","text":"commercial system"},{"key":"D","text":"rapid production"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes Basho''s later haiku as achieving resonance through the "sparest possible arrangement" where "each syllable" carries maximum weight, indicating that "economy" here means deliberate restraint in the use of language. "Financial arrangement" applies the monetary sense of the word, which is irrelevant to literary technique. "Commercial system" similarly invokes the marketplace meaning and has no bearing on poetic composition. "Rapid production" misreads the passage''s emphasis on compression and precision as a comment on speed of composition, which the passage does not address.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G7UKUB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Herschel Space Observatory, which orbited a gravitationally stable point 1.5 million kilometers from Earth collecting infrared data on star-forming _______ provided critical evidence that massive clouds of cold interstellar gas serve as incubators for newly emerging stellar systems.', $lyceon_json$[{"key":"A","text":"regions provided"},{"key":"B","text":"regions; provided"},{"key":"C","text":"regions. Provided"},{"key":"D","text":"regions, provided"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence contains a nonrestrictive relative clause beginning with "which orbited" and set off by a comma after "Observatory." This clause must be closed with a matching comma before the main verb "provided." The version with a comma after "regions" correctly closes the nonrestrictive clause, yielding the structure: "The Herschel Space Observatory, which orbited...regions, provided critical evidence..." Omitting the closing comma disrupts the paired-comma structure required for nonrestrictive clauses. A semicolon cannot close a nonrestrictive clause because the material before it is not an independent clause. A period after "regions" would leave "The Herschel Space Observatory, which orbited...regions." as a sentence fragment lacking a main verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HMS67B', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The museum''s newest acquisition—a tapestry woven by artisans in fifteenth-century _______ required three conservators working in shifts over eleven months to stabilize its deteriorating silk threads before it could be put on public display.', $lyceon_json$[{"key":"A","text":"Bruges, required"},{"key":"B","text":"Bruges: required"},{"key":"C","text":"Bruges—required"},{"key":"D","text":"Bruges; required"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence uses a pair of em dashes to set off a parenthetical description ("a tapestry woven by artisans in fifteenth-century Bruges"). The opening em dash appears after "acquisition," so a matching closing em dash must appear after "Bruges" to properly close the parenthetical before the main verb "required." Using a comma after "Bruges" fails to match the opening em dash, creating inconsistent punctuation. A colon after "Bruges" is syntactically incorrect in this position because the parenthetical is an aside, not an introduction to an explanation. A semicolon cannot close an em-dash parenthetical and would incorrectly suggest two independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JKANEG', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a presentation about the tardigrade and has gathered the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KNPHBD', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Glaciologists studying the Vatnajokull ice cap in Iceland have observed that certain outlet glaciers accelerate dramatically during late summer, a period when surface meltwater penetrates to the glacier bed through vertical channels called moulins. The meltwater lubricates the interface between the ice and the bedrock, reducing friction. However, by early autumn, the subglacial drainage system reorganizes into efficient conduits that channel water away rapidly, restoring higher friction levels. This seasonal pattern suggests that ________', $lyceon_json$[{"key":"A","text":"the relationship between meltwater and glacier speed is not simply linear, because drainage efficiency can counteract the lubricating effect of additional water."},{"key":"B","text":"glaciers in Iceland move faster than glaciers in all other regions due to the island's high geothermal activity."},{"key":"C","text":"moulins form only during years when summer temperatures exceed the historical average by at least two degrees."},{"key":"D","text":"the bedrock beneath Vatnajokull is composed primarily ofite, which has an unusually smooth surface."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a pattern where meltwater first accelerates the glacier by reducing friction, but then a reorganized drainage system restores friction. The logical completion is that the relationship between meltwater and glacier speed is not simply linear because efficient drainage can counteract lubrication. The choice about Icelandic glaciers moving faster than all others introduces a global comparison unsupported by the passage. The choice about moulins forming only in above-average temperature years introduces a condition not mentioned or implied in the text. The choice about bedrock composition introduces a specific geological claim with no basis in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LZ9ZUJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Behavioral economists have long documented the "endowment effect," whereby people value an object more highly once they own it. In a series of experiments conducted at the University of Lisbon, however, psychologist Marta Ferreira found that the endowment effect was significantly attenuated when participants were asked to make ownership decisions on behalf of another person rather than for themselves. Participants serving as proxies assigned valuations to owned objects that were, on average, only 7 percent higher than their market estimates, compared with the 43 percent premium observed among participants deciding for themselves. Ferreira concluded that ________', $lyceon_json$[{"key":"A","text":"the endowment effect is driven largely by personal emotional attachment to ownership rather than by a purely cognitive bias in estimating value."},{"key":"B","text":"proxy decision-makers are generally less intelligent than people who make decisions for themselves."},{"key":"C","text":"the endowment effect occurs only in laboratory settings and has no relevance to real-world economic behavior."},{"key":"D","text":"participants at the University of Lisbon are not representative of the broader population because of their unusually high income levels."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that when personal ownership is removed from the equation (proxy decisions), the valuation premium drops from 43 percent to 7 percent. The logical conclusion Ferreira would draw is that personal emotional attachment to ownership, rather than a purely cognitive estimation bias, drives the effect. The choice about proxy decision-makers being less intelligent has no support in the passage and introduces an irrelevant and unfounded claim. The choice dismissing the endowment effect as limited to laboratories contradicts the passage, which treats the effect as an established behavioral phenomenon. The choice about Lisbon participants being unrepresentative due to income levels introduces demographic details absent from the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M53KEX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about glassblowing and has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MCAYA7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Historian Kenji Yamamoto has examined how seventeenth-century Japanese lacquerware artisans adapted their techniques when producing objects for Dutch East India Company traders. While domestic Japanese lacquerware emphasized restrained monochrome surfaces with subtle textural variation, the export pieces incorporated elaborate gold-leaf landscapes and figurative scenes that had no parallel in contemporary Japanese decorative arts. Yamamoto notes that these export designs were not, as previously assumed, direct copies of European motifs supplied by Dutch merchants. Instead, the artisans drew on visual conventions from Chinese painted screens and Mughal miniatures—traditions they encountered through the port city of Nagasaki''s multicultural trade networks. This finding complicates the standard narrative of European cultural dominance in early modern trade because it suggests that ________', $lyceon_json$[{"key":"A","text":"Japanese artisans exercised creative agency by selectively synthesizing multiple Asian visual traditions to meet foreign demand, rather than passively reproducing European designs."},{"key":"B","text":"Dutch East India Company traders preferred Chinese decorative styles over Japanese ones and therefore refused to purchase standard domestic lacquerware."},{"key":"C","text":"seventeenth-century Japanese lacquerware was technically inferior to Chinese and Mughal decorative arts, which is why artisans borrowed from those traditions."},{"key":"D","text":"the port city of Nagasaki was the only location in Japan where foreign trade was permitted during the seventeenth century."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage argues that the export designs were not copies of European motifs but rather drew on Chinese and Mughal visual traditions encountered through Nagasaki''s trade networks. This complicates the narrative of European cultural dominance by showing Japanese artisans exercised creative agency, synthesizing multiple Asian traditions rather than passively reproducing European designs. The choice about Dutch traders preferring Chinese styles and refusing domestic lacquerware goes well beyond the passage, which does not discuss trader preferences or refusals. The choice about Japanese lacquerware being technically inferior introduces a qualitative judgment absent from the passage; borrowing visual conventions does not imply technical inferiority. The choice about Nagasaki being the only permitted trade location states a historical fact that may be true but is not the logical completion of the argument about complicating narratives of European cultural dominance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MGQ1VZ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists studying the pine forests of central Siberia have hypothesized that the Siberian nutcracker (Nucifraga caryocatactes) plays an irreplaceable role in the regeneration of Siberian stone pine (Pinus sibirica). The birds cache pine seeds in shallow soil deposits across the forest floor, and seeds that go unretrieved germinate the following spring. The researchers suggest that without the nutcracker''s caching behavior, stone pine regeneration would decline substantially because the heavy, wingless seeds cannot disperse effectively by wind or gravity alone.', $lyceon_json$[{"key":"A","text":"In forest areas where nutcracker populations have been eliminated by habitat loss, stone pine seedling establishment has dropped by over 80 percent compared to areas with stable nutcracker populations."},{"key":"B","text":"Siberian nutcrackers prefer to cache seeds from stone pines rather than from other conifer species in the same forest."},{"key":"C","text":"Stone pine seeds contain higher concentrations of fat and protein than the seeds of most other Siberian conifers."},{"key":"D","text":"Nutcracker populations in central Siberia have remained stable over the past three decades despite changes in winter temperature."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that without nutcracker caching, stone pine regeneration would decline substantially. The finding showing an 80 percent drop in seedling establishment where nutcracker populations have been eliminated directly supports this claim by demonstrating the predicted outcome. The finding about nutcrackers preferring stone pine seeds over other conifers addresses seed selection preferences, not the effect on regeneration. The finding about seed nutritional content explains why nutcrackers might favor the seeds but does not address whether pine regeneration depends on the birds. The finding about stable nutcracker populations over three decades concerns population trends, not the causal link between caching behavior and pine regeneration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MU69F1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The orchestra''s decision to perform the rarely heard symphony—a piece that _______ extreme technical demands on the brass section—was met with enthusiasm by critics who had long championed the composer''s lesser-known works.', $lyceon_json$[{"key":"A","text":"placing"},{"key":"B","text":"are placing"},{"key":"C","text":"places"},{"key":"D","text":"place"}]$lyceon_json$::jsonb, 'C', NULL, E'The relative clause "that _______ extreme technical demands on the brass section" modifies "a piece," which is singular. The singular present-tense verb "places" correctly agrees with "a piece." The participial form "placing" cannot serve as the main verb of the relative clause because it lacks a finite form. "Are placing" uses a plural auxiliary that does not agree with the singular antecedent "piece." The base form "place" is plural present tense and fails to agree with the singular "piece."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O6SPVR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The fruit fly Drosophila melanogaster has long been a staple of genetics research, prized for its short reproductive cycle and well-mapped genome. _______ researchers at the University of Lausanne recently used the organism to identify seventeen previously unknown genes linked to cardiac development.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence provides a specific, recent example that reinforces the claim made in the first sentence about the fruit fly''s value in genetics research. "In fact," correctly signals that what follows supports and extends the preceding point. "Nevertheless," "In contrast," and "On the other hand," all introduce a contradictory or opposing relationship, which does not match the logical connection between the two sentences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QBMQ9G', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "tempered" most nearly means', E'The blacksmith''s initial fury at discovering the ruined mold was tempered by the realization that his apprentice had simultaneously produced an alloy stronger than any the workshop had previously forged. Though the setback would cost them a week''s labor, the potential gains far outweighed the loss.', $lyceon_json$[{"key":"A","text":"heated"},{"key":"B","text":"moderated"},{"key":"C","text":"destroyed"},{"key":"D","text":"concealed"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes how the blacksmith''s fury was reduced or softened by the compensating discovery, making "moderated" the correct choice. "Heated" relates to the metallurgical meaning of tempering metal but does not fit the emotional context here. "Destroyed" overstates the effect, since the passage indicates the fury was lessened rather than eliminated. "Concealed" implies the anger was hidden, but the passage describes an actual change in the emotional response, not a masking of it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R49505', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1987, marine biologist Cindy Lee Van Dover discovered that the vent shrimp Rimicaris exoculata, found near hydrothermal vents on the Mid-Atlantic Ridge, possesses a novel photoreceptor organ on its back rather than conventional eyes. This organ is sensitive to the faint thermal radiation emitted by superheated vent fluid at temperatures exceeding 350 degrees Celsius. Van Dover hypothesized that the shrimp use this organ to navigate toward active vents while avoiding direct contact with lethally hot plumes. Subsequent research confirmed that the photoreceptor degrades when shrimp are removed from vent environments, suggesting it is specifically adapted to deep-sea thermal light rather than to ambient sunlight.', $lyceon_json$[{"key":"A","text":"Rimicaris exoculata has a specialized photoreceptor adapted to detect thermal radiation from hydrothermal vents, enabling it to navigate safely in that environment."},{"key":"B","text":"Cindy Lee Van Dover's career was shaped by her interest in understanding how deep-sea organisms adapt to extreme pressure."},{"key":"C","text":"The photoreceptor organ of Rimicaris exoculata functions identically to the eyes of shallow-water shrimp species."},{"key":"D","text":"Hydrothermal vents on the Mid-Atlantic Ridge produce more thermal radiation than vents in the Pacific Ocean."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage focuses on the discovery that Rimicaris exoculata has an unusual photoreceptor organ adapted to thermal radiation near hydrothermal vents, which enables the shrimp to navigate safely. The choice about Van Dover''s career being shaped by extreme pressure interest misreads the passage, which discusses her discovery of the photoreceptor rather than her broader career motivations. The choice claiming the organ functions identically to shallow-water shrimp eyes contradicts the passage, which emphasizes that the organ is novel and specifically adapted to deep-sea thermal light. The choice comparing vent radiation levels between ocean regions introduces a claim not found anywhere in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S5UH92', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleontologist Mary Schweitzer''s 2005 discovery of soft tissue inside a Tyrannosaurus rex femur challenged the widely held assumption that organic material could not survive more than a few hundred thousand years. Some skeptics attributed the finding to bacterial contamination rather than preserved dinosaur tissue. _______ subsequent analyses using mass spectrometry confirmed the presence of collagen sequences matching those of modern birds, lending substantial support to the original claim.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Accordingly,"},{"key":"C","text":"However,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage moves from skeptics attributing the finding to contamination to subsequent analyses that actually confirmed the original discovery. The final sentence contradicts the skeptics'' position, so "However," correctly signals this shift. "Similarly," would indicate the analyses agreed with the skeptics, but they did the opposite. "Accordingly," implies the analyses followed logically from the skeptics'' objection as a consequence, but the results actually undermined the objection rather than acting on it. "For instance," would frame the analyses as an example of the skepticism, when they instead refute it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TO0KH6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The research team''s lead linguist insisted that each participant in the longitudinal study _______ a daily journal documenting their language interactions, a requirement that some critics argued placed an unreasonable burden on volunteers already committing several hours per week to the project.', $lyceon_json$[{"key":"A","text":"maintains"},{"key":"B","text":"maintained"},{"key":"C","text":"would maintain"},{"key":"D","text":"maintain"}]$lyceon_json$::jsonb, 'D', NULL, E'The verb "insisted" followed by a "that" clause requires the subjunctive mood in Standard English. The subjunctive uses the base form of the verb regardless of the subject, so "maintain" is correct even though the subject "each participant" is singular. The indicative form "maintains" incorrectly applies standard subject-verb agreement instead of the subjunctive. The past-tense "maintained" incorrectly treats the clause as indicative past rather than subjunctive. The conditional "would maintain" is inappropriate because the subjunctive, not the conditional mood, is required after verbs of demand and insistence in formal Standard English.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
