INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WP5X6U', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which choice best describes data that would weaken the claim made in the text?', E'A team of urban climatologists has claimed that the installation of reflective white roofing materials in densely built neighborhoods can reduce local surface temperatures by as much as 5 degrees Celsius during peak summer months. The researchers argue that this reduction occurs because white surfaces reflect a larger proportion of incoming solar radiation back into the atmosphere, preventing heat absorption by building structures. They further assert that widespread adoption of reflective roofing could meaningfully lower energy consumption for air conditioning across entire metropolitan areas.', $lyceon_json$[{"key":"A","text":"Data showing that neighborhoods with white roofs experienced surface temperature reductions of only 0.3 degrees Celsius, well within natural measurement variability, during a three-year monitoring period."},{"key":"B","text":"Data showing that white roofing materials cost approximately 15 percent more to install than conventional dark-colored roofing."},{"key":"C","text":"Data showing that reflective roofing has been adopted by several municipalities in southern Europe as part of climate adaptation plans."},{"key":"D","text":"Data showing that dark-colored roofs absorb more solar radiation than lighter-colored surfaces under controlled laboratory conditions."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers claim white roofing can reduce surface temperatures by up to 5 degrees Celsius. Data showing only a 0.3-degree reduction within natural variability directly weakens this claim by suggesting the real-world effect is negligible. The data about installation costs addresses economic feasibility, not the temperature reduction claim. The data about municipal adoption in Europe shows policy interest but says nothing about whether the temperature claim is accurate. The data about dark roofs absorbing more radiation under laboratory conditions actually supports the underlying mechanism of the researchers'' claim rather than weakening it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XODD0N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After analyzing soil samples from seventeen different marshland sites in eastern _______ botanist Dr. Kendra Osei confirmed that the high salinity levels were inhibiting root development in native grasses.', $lyceon_json$[{"key":"A","text":"Georgia; botanist"},{"key":"B","text":"Georgia botanist"},{"key":"C","text":"Georgia, botanist"},{"key":"D","text":"Georgia: botanist"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence begins with a long introductory prepositional phrase ("After analyzing soil samples from seventeen different marshland sites in eastern Georgia"), which must be followed by a comma before the main clause. The version with a comma correctly separates the introductory phrase from the independent clause. Using a semicolon is incorrect because a semicolon requires independent clauses on both sides, and the introductory phrase is dependent. Omitting punctuation entirely produces a run-on. A colon is inappropriate after a dependent introductory phrase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y0A0CR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the Brazilian composer Chiquinha Gonzaga wrote over two thousand works spanning waltzes, polkas, and tangos. Her compositions drew from both European classical traditions and Afro-Brazilian musical forms. _______ her 1899 march "O Abre Alas" became the first recorded Carnival song, cementing her role in shaping Brazil''s national musical identity.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Nonetheless,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Conversely,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage builds from Gonzaga''s prolific output and blending of musical traditions to an additional, crowning achievement: composing the first recorded Carnival song. "Moreover," correctly signals that the final sentence adds further significant information to what precedes it. "Specifically," would imply the sentence is narrowing or illustrating the preceding claim about musical forms, but the Carnival song is a new accomplishment rather than an example of her stylistic blending. "Nonetheless," and "Conversely," both incorrectly suggest contrast or opposition between the sentences.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YGPFYB', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Literary scholar Haruo Shirane has argued that the Japanese aesthetic concept of mono no aware—often translated as "the pathos of things"—has been systematically mischaracterized in Western criticism. While Western commentators typically equate mono no aware with a passive melancholy triggered by the transience of beauty, Shirane contends that the concept originally encompassed a far wider emotional register, including joy, wonder, and even anger, as articulated in the writings of the eighteenth-century scholar Motoori Norinaga. Norinaga defined mono no aware as a deep emotional responsiveness to the world that could manifest in any affective state, not merely sorrow. According to Shirane, the narrowing of mono no aware to wistful sadness reflects nineteenth-century European Romantic projections onto Japanese culture rather than the concept''s authentic intellectual history.', $lyceon_json$[{"key":"A","text":"Western criticism has narrowed mono no aware to melancholy, but the concept originally encompassed a broad range of emotional responses."},{"key":"B","text":"Motoori Norinaga was the first Japanese scholar to define mono no aware as an aesthetic concept in the eighteenth century."},{"key":"C","text":"The translation of mono no aware as \"the pathos of things\" accurately captures the full meaning of the original Japanese term."},{"key":"D","text":"Nineteenth-century European Romanticism had no significant influence on how Japanese aesthetic concepts were interpreted in the West."}]$lyceon_json$::jsonb, 'A', NULL, E'Shirane''s central claim, as presented in the passage, is that Western criticism has mischaracterized mono no aware by reducing it to passive melancholy, when Norinaga''s original formulation included a much broader emotional register. The choice about Norinaga being the first to define the concept captures a supporting detail but not the passage''s central argument, which is about the Western mischaracterization. The choice suggesting the translation accurately captures the full meaning contradicts the passage, which indicates the translation contributes to a misleading narrowing. The choice denying European Romantic influence directly contradicts the passage''s assertion that nineteenth-century Romantic projections caused the narrowing of the concept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZL3LUX', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban ecologist Paige Warren has documented that mid-sized cities with fragmented green spaces often support higher bird species diversity than cities with a single large park of equivalent total area. Warren attributes this to edge habitats created at boundaries between developed land and vegetation patches, which provide nesting sites unavailable in park interiors. _______ her findings suggest that the spatial distribution of green space, not merely its total acreage, is a critical variable in urban biodiversity planning.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Regardless,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence restates Warren''s core finding in broader, more general terms: what matters is how green space is distributed, not just the total amount. "In other words," correctly signals a restatement or clarification of the preceding idea. "By contrast," incorrectly implies the final sentence opposes the previous information. "Regardless," suggests the conclusion holds despite the prior evidence, but the conclusion actually follows from it. "For example," would frame the final sentence as a specific illustration, yet it is a summary generalization rather than a concrete instance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
